import React from 'react';
import type { Meta, StoryObj } from "@storybook/nextjs";
import { Separator } from "./Separator";
import { Box, Flex, Text } from "../index";

const meta: Meta<typeof Separator> = {
  title: "Design System/Atoms/Separator",
  component: Separator,
  parameters: {
    docs: {
      description: {
        component: `A visual separator component for dividing content sections. Built on Radix UI Separator primitive with support for horizontal and vertical orientations. Purely decorative by default (does not affect screen reader navigation).

**Accessibility:**
- Decorative by default: Uses \`aria-hidden="true"\` to hide from screen readers
- Semantic separators: Set \`decorative={false}\` to create a proper separator landmark
- ARIA role: Non-decorative separators use \`role="separator"\`
- Orientation: Properly announced to assistive technologies via \`aria-orientation\`

**Best practices:**
- Use horizontal separators (default) to divide vertical content stacks
- Use vertical separators for side-by-side content or navigation items
- Adjust thickness via CSS height (horizontal) or width (vertical)
- Match separator color to design system tokens (\$bg04, \$bg05, etc.)
- Leave decorative={true} for visual-only separators (most common use case)`,
      },
    },
  },
  argTypes: {
    orientation: {
      control: { type: 'select' },
      options: ['horizontal', 'vertical'],
      description: 'Orientation of the separator',
      table: {
        type: { summary: '"horizontal" | "vertical"' },
        defaultValue: { summary: 'horizontal' },
      },
    },
    decorative: {
      control: 'boolean',
      description: 'Whether the separator is purely decorative (hidden from screen readers)',
      table: {
        type: { summary: 'boolean' },
        defaultValue: { summary: 'true' },
      },
    },
    css: {
      control: 'object',
      description: 'Custom Stitches CSS styling (commonly: width, height, backgroundColor, margin)',
      table: {
        type: { summary: 'CSS' },
      },
    },
  },
};

export default meta;
